import { listCustomers } from './customers.js';

/** Quotes a CSV field when it contains a comma, quote, or line break. */
function csvField(value) {
  const text = String(value ?? '');
  return /[",\r\n]/.test(text) ? `"${text.replaceAll('"', '""')}"` : text;
}

/**
 * Returns the customers as CSV text: the header `id,name,region`, then one
 * line per customer, sorted by id (the store's order is not stable).
 */
export function exportCustomersCsv() {
  const rows = listCustomers()
    .sort((a, b) => (a.id < b.id ? -1 : a.id > b.id ? 1 : 0))
    .map((customer) => [customer.id, customer.name, customer.region].map(csvField).join(','));
  return ['id,name,region', ...rows].join('\n');
}

